    return {
      name: 'Sample User',
      email: 'sample.user@example.com',
    }
  }
}

export default async function UserProfile() {
  const user = await getUserProfile()

  return (
    <div>
      <h2>User Profile</h2>
      <div>{user.name}</div>
      <div>{user.email}</div>
    </div>
  )
}
